/**
 * Mapping of mouse event names to underlying browser event names.
 */
export type MouseEvents = {
    'MOUSEDOWN': string;
    'MOUSEUP': string;
    'MOUSECANCEL': string;
    'MOUSEMOVE': string;
    'MOUSEOVER': string;
    'MOUSEOUT': string;
    'MOUSEENTER': string;
    'MOUSELEAVE': string;
};
